async function verifySignature(
  payload: string,
  signatureHeader: string | null,
  secret: string,
): Promise<void> {
  if (!signatureHeader) {
    throw new Error('Missing X-Hub-Signature-256 header')
  }
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(payload).digest('hex')
  if (!crypto.timingSafeEqual(Buffer.from(signatureHeader), Buffer.from(expected))) {
    throw new Error('Invalid webhook signature')
  }
}

function hasBugLabel(labels: Array<{ name: string }>): boolean {
  return labels.some((label) => label.name === 'bug')
}

export async function handle(
  payload: GitHubIssuePayload,
  config: ConnectorConfig,
): Promise<LinearIssueCreateResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  if (!payload.action) throw new Error('Missing required field: action')
  if (!payload.issue) throw new Error('Missing required field: issue')
  if (!payload.issue.title) throw new Error('Missing required field: issue.title')
  if (!payload.issue.body) throw new Error('Missing required field: issue.body')
  if (!payload.issue.labels) throw new Error('Missing required field: issue.labels')
  if (!payload.issue.user?.login) throw new Error('Missing required field: issue.user.login')
  if (!payload.issue.html_url) throw new Error('Missing required field: issue.html_url')
  if (!payload.repository?.full_name) throw new Error('Missing required field: repository.full_name')

  // Only process 'labeled' action with 'bug' label
  if (payload.action !== 'labeled') {
    throw new Error(`Unsupported action: ${payload.action}. Only 'labeled' is supported.`)
  }
  if (!hasBugLabel(payload.issue.labels)) {
    throw new Error('Issue does not have the "bug" label')
  }

  // Verify webhook signature (in real usage, the raw body and header would be passed separately)
  // For this connector, we assume the payload is already validated by the webhook handler
  // The signature verification would happen at the HTTP layer before calling handle()

  // Build GraphQL mutation for Linear
  const mutation = `
    mutation IssueCreate {
      issueCreate(input: {
        title: ${JSON.stringify(payload.issue.title)},
        description: ${JSON.stringify(payload.issue.body)},
        teamId: ${JSON.stringify(config.linearTeamId)}
      }) {
        success
        issue {
          id
          title
        }
      }
    }
  `.trim()

  const response = await fetchImpl('https://api.linear.app/graphql', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: config.linearApiKey,
    },
    body: JSON.stringify({ query: mutation }),
  })

  if (!response.ok) {
    throw new Error(`Linear API error: ${response.status} ${response.statusText} at POST https://api.linear.app/graphql`)
  }

  const data = (await response.json()) as {
    data?: {
      issueCreate?: {
        success: boolean
        issue?: { id: string; title: string }
      }
    }
    errors?: Array<{ message: string }>
  }

  if (data.errors?.length) {
    throw new Error(`Linear GraphQL errors: ${data.errors.map((e) => e.message).join(', ')}`)
  }

  const issueCreate = data.data?.issueCreate
  if (!issueCreate?.success || !issueCreate.issue?.id) {
    throw new Error('Linear issue creation failed: unexpected response format')
  }

  return {
    linearIssueId: issueCreate.issue.id,
    linearIssueTitle: issueCreate.issue.title,
  }
}

